// Release signing for the POS APK (docs/claude/production.md "Release signing"). android/ is generated by
// `expo prebuild`, so the signing setup lives here and is re-applied on every prebuild.
//
// NOTHING SECRET IS IN THE REPO. The keystore path, alias and both passwords come from Gradle properties or
// environment variables of the machine that builds — normally %USERPROFILE%\.gradle\gradle.properties:
//   GAMOTERP_POS_RELEASE_STORE_FILE     e.g. D:/keys/gamoterp-pos-release.keystore
//   GAMOTERP_POS_RELEASE_KEY_ALIAS      e.g. gamoterp-pos
//   GAMOTERP_POS_RELEASE_STORE_PASSWORD
//   GAMOTERP_POS_RELEASE_KEY_PASSWORD   (PKCS12: the same as the store password)
// None set → the release build is signed with the debug key, as before (dev / sideload test builds), and Gradle says so.
// Some set but not all, or the file missing → the build FAILS (never a silently debug-signed "release").
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// gamoterp-pos release signing (plugins/withReleaseSigning.js)';

const HELPER = `${MARKER}
def gamoterpPosSigning = { String name ->
    def v = findProperty(name) ?: System.getenv(name)
    return v == null ? null : v.toString().trim()
}
def gamoterpPosStoreFile = gamoterpPosSigning('GAMOTERP_POS_RELEASE_STORE_FILE')
def gamoterpPosSigningValues = [
    gamoterpPosStoreFile,
    gamoterpPosSigning('GAMOTERP_POS_RELEASE_KEY_ALIAS'),
    gamoterpPosSigning('GAMOTERP_POS_RELEASE_STORE_PASSWORD'),
    gamoterpPosSigning('GAMOTERP_POS_RELEASE_KEY_PASSWORD'),
]
def gamoterpPosReleaseKey = gamoterpPosSigningValues.any { it }
if (gamoterpPosReleaseKey) {
    if (!gamoterpPosSigningValues.every { it }) {
        throw new GradleException('GamotERP POS release signing: set all four GAMOTERP_POS_RELEASE_* values (store file, key alias, store password, key password) or none')
    }
    if (!file(gamoterpPosStoreFile).isFile()) {
        throw new GradleException("GamotERP POS release signing: keystore not found: \${gamoterpPosStoreFile}")
    }
    logger.lifecycle("GamotERP POS: release APK signed with \${gamoterpPosStoreFile} (alias \${gamoterpPosSigning('GAMOTERP_POS_RELEASE_KEY_ALIAS')})")
} else {
    logger.warn('GamotERP POS: GAMOTERP_POS_RELEASE_* not set — the release APK is signed with the DEBUG key (test builds only)')
}

`;

const RELEASE_CONFIG = `
        release {
            if (gamoterpPosReleaseKey) {
                storeFile file(gamoterpPosStoreFile)
                storePassword gamoterpPosSigning('GAMOTERP_POS_RELEASE_STORE_PASSWORD')
                keyAlias gamoterpPosSigning('GAMOTERP_POS_RELEASE_KEY_ALIAS')
                keyPassword gamoterpPosSigning('GAMOTERP_POS_RELEASE_KEY_PASSWORD')
            }
        }`;

function applyReleaseSigning(gradle) {
  if (gradle.includes(MARKER)) return gradle;
  let out = gradle;
  // 1. The helper, before the android { } block.
  const androidAt = out.search(/^android\s*\{/m);
  if (androidAt < 0) throw new Error('withReleaseSigning: no "android {" block in app/build.gradle');
  out = out.slice(0, androidAt) + HELPER + out.slice(androidAt);
  // 2. A `release` signing config next to `debug` (inside signingConfigs { }).
  const debugConfig = /(signingConfigs\s*\{\s*debug\s*\{[^}]*\})/m;
  if (!debugConfig.test(out)) throw new Error('withReleaseSigning: no signingConfigs { debug { … } } in app/build.gradle');
  out = out.replace(debugConfig, (m) => m + RELEASE_CONFIG);
  // 3. The release build type uses it when configured (the template signs release with the debug key).
  const releaseType = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/m;
  if (!releaseType.test(out)) throw new Error('withReleaseSigning: no release build type signed with signingConfigs.debug');
  out = out.replace(releaseType, (_m, head) => `${head}signingConfig gamoterpPosReleaseKey ? signingConfigs.release : signingConfigs.debug`);
  return out;
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') throw new Error('withReleaseSigning: app/build.gradle must be Groovy');
    cfg.modResults.contents = applyReleaseSigning(cfg.modResults.contents);
    return cfg;
  });
};
module.exports.applyReleaseSigning = applyReleaseSigning;
